CREATE TABLE IF NOT EXISTS doc_sequences (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, doc_type VARCHAR(50) NOT NULL UNIQUE, prefix VARCHAR(30) NOT NULL, last_value BIGINT UNSIGNED NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS counters (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, opening_cash DECIMAL(14,2) NOT NULL DEFAULT 0.00, active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO doc_sequences(doc_type,prefix,last_value) VALUES ('SALE','SAL-',0),('RECEIPT','RCT-',0) ON DUPLICATE KEY UPDATE prefix=VALUES(prefix);
INSERT INTO counters(name,opening_cash,active) VALUES ('Main Counter',0,1) ON DUPLICATE KEY UPDATE active=VALUES(active);